# Master inventory of Table 1 (Bruegel / kaizenner.eu "Overview of EU Legislation in the Digital Sector", mid-2023)
# status_in_table is taken from the cell colour in the PDF; current_status was checked against OEIL / Cellar on 2026-10-09.
# docs: (role, celex, note)
#   role: in_force   = the act the table lists as applicable law (latest consolidated version is downloaded)
#         adopted    = final act adopted from the procedure the table lists
#         proposal   = Commission proposal (COM) the table refers to
#         related    = not named in the table but needed to read the entry (e.g. the law a withdrawn proposal would have replaced)
import json, csv, sys

A, N, P = "applicable", "in_negotiation", "planned"
E = []
def e(no, status, cat, short, label, refs, current, docs, extract):
    E.append(dict(no=no, status_in_table=status, category=cat, short=short, table_label=label,
                  table_refs=refs, current_status=current,
                  docs=[dict(role=r, celex=c, note=n) for r, c, n in docs], extract_from=extract))

